function begin(){if(mode==='story')selectedDistrict=12;const cfg={mode,edition:edition==='custom'?76:Number(edition),district:selectedDistrict,name:$('#player-name')?.value.trim()||'Tributo del Distrito '+selectedDistrict,arena:mode==='story'?(edition===50?'Pradera de flores venenosas':edition===74?'Bosque y lago':'Arena del reloj'):($('#arena')?.value||'Bosque templado'),shared:$('#shared')?.value||'canon',difficulty:$('#difficulty')?.value||'normal'};let tributes=makeTributes();const wi=mode==='free'&&whatIf&&(whatIf.base!=='original'||whatIf.preset||whatIf.edited)?whatIf:null;if(wi)tributes=WI.buildTributes(wi);game={...cfg,phase:'harvest',day:0,health:100,hunger:0,thirst:0,skill:6,rebellion:0,support:12,favor:40,tributes,log:[],decisions:[],inventory:['ropa de tributo'],wounds:[],injuries:[],equippedWeapon:'ninguna',combatStance:'balanced',fatigue:0,stealth:0,interviewScore:0,sponsorTrust:0,president:null};if(mode==='story'&&cfg.edition===50){game.tributes=buildRoster50().map(t=>({...t,x:10+Math.random()*80,y:10+Math.random()*80,skill:5+Math.floor(Math.random()*5)}));game.preArena50=createPreArena50State();game.phase='prearena50';}if(mode==='story'&&cfg.edition===50){game.name='Haymitch Abernathy';game.district=12;}if(mode==='story'&&(cfg.edition===74||cfg.edition===75)){game.name='Katniss Everdeen';game.district=12;}
if(wi)game.whatIf={text:WI.describe(wi),playerId:wi.playerId};const wiPlayer=wi&&wi.playerId?game.tributes.find(t=>t.id===wi.playerId):null;const player=wiPlayer||game.tributes.find(t=>t.district===game.district);if(player){if(wiPlayer){game.name=player.name;game.district=player.district;}else player.name=mode==='story'?(cfg.edition===50?'Haymitch Abernathy':'Katniss Everdeen'):game.name;player.player=true;}initArenaState();game.log.push('La cosecha ha terminado. El Capitolio inicia la retransmisión.');$('#save-indicator').textContent='PARTIDA ACTIVA';renderGame();}
function campaignText(){if(game.edition===50)return 'El Segundo Vasallaje exige cuatro tributos por distrito: cuarenta y ocho en total. Haymitch llega a una Arena diseñada para castigar cada error.';if(game.edition===74)return 'La cosecha del Distrito 12 ha cambiado una vida: Katniss se ofrece voluntaria por Prim. El destino de los tributos ya no está escrito.';if(game.mode==='free'&&game.whatIf?.text)return `${game.whatIf.text} Desde aquí, nada está escrito.`;if(game.mode==='free')return `Edición original: ${game.tributes?.length||24} tributos, Arena «${game.arena}» y reglas definidas por ti. Ningún resultado está escrito de antemano.`;return 'El Capitolio elige a sus tributos entre los vencedores vivos. El Vasallaje se convierte en una trampa política y en el inicio de una ruptura.';}
