// Al arrancar se reconcilian la copia local y la nativa (Android). Partidas y ajustes esperan a que termine.
const nativeStore=DS.nativePreferences(typeof window==='undefined'?null:window);let storeReady=!nativeStore?null:DS.hydrate(localStorage,nativeStore,DURABLE_KEYS,(k,t)=>k===ST.SETTINGS_KEY||k===SV.MIGRATED_KEY||SV.isValidSlotText(t)).then(r=>{storeReport=r;if(r.restored.length||r.resolved.length){prefs=ST.loadSettings(store);soundOn=prefs.sound;ST.applySettings(prefs,document);}if(document.documentElement)document.documentElement.dataset.storage=r.native?'nativo':'local';return r;}).catch(e=>{console.warn('No se pudo reconciliar el guardado:',e);return null;}).finally(()=>{storeReady=null;});
function whenStoreReady(fn){if(storeReady)storeReady.then(()=>fn());else fn();}
if(document.addEventListener)document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')store.flush();});// Android: sin service worker (los archivos van en el APK). Se retira el de versiones anteriores y su caché.
if('serviceWorker'in navigator)navigator.serviceWorker.getRegistrations().then(rs=>Promise.all(rs.map(r=>r.unregister()))).then(()=>typeof caches!=='undefined'?caches.keys().then(ks=>Promise.all(ks.map(k=>caches.delete(k)))):null).catch(()=>{});

document.addEventListener('change',e=>{if(e.target.id==='set-volume'){setSetting('volume',Number(e.target.value)/100);const o=document.querySelector('#set-volume-value');if(o)o.textContent=Math.round(prefs.volume*100)+' %';sound();return;}if(e.target.id==='import-save-file'){importSaveFile(e.target.files?.[0]);e.target.value='';}if(e.target.id==='p-character'){const n=document.querySelector('#p-name');if(n&&['Snow','Alma Coin','Plutarch Heavensbee'].includes(e.target.value))n.value=e.target.value==='Snow'?'Coriolanus Snow':e.target.value;}if(e.target.id==='p-origin'&&e.target.value==='Personaje original generado'){const a=['Aurelia','Cassian','Livia','Darian','Octavia','Lucan','Seraphine','Marcellus'];const b=['Vale','Draven','Voss','Thorne','Ravelle','Soren','Morrow','Kestrel'];const name=a[Math.floor(Math.random()*a.length)]+' '+b[Math.floor(Math.random()*b.length)];const input=document.querySelector('#p-name');if(input)input.value=name;const bio=document.querySelector('#p-bio');if(bio&&!bio.value)bio.value='Ascendiste desde una familia influyente o desde los márgenes del Capitolio. Tus alianzas y decisiones definirán tu legado.';}});
